<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api,can,type Metric,type TrendQuantity,type Configuration,type HistoryPage} from './api';
import {displayMetric,unit,qualityNames,type Quantity} from './units';
import {previewPrint} from './printPreview';
import DataJobs from './DataJobs.vue';
const props=defineProps<{config:Configuration}>();
type Item=TrendQuantity|'Interface';type Row=HistoryPage['rows'][number];
const page=ref<HistoryPage|null>(null),tank=ref('all'),start=ref(localInput(Date.now()-3600000)),end=ref(localInput(Date.now()+60000)),ats=ref(false),error=ref(''),message=ref(''),busy=ref(false),jobs=ref<InstanceType<typeof DataJobs>|null>(null),basis=ref<Row|null>(null);
const quantity=ref<TrendQuantity>('Level'),quality=ref('All');
const definitions:{id:Item;name:string;field:keyof Row;unit:Quantity|'pressure'}[]=[{id:'Level',name:'液位',field:'levelMm',unit:'level'},{id:'Interface',name:'界位',field:'interfaceMm',unit:'level'},{id:'InstantTemperature',name:'温度',field:'instantTemperatureC',unit:'temperature'},{id:'AverageTemperature',name:'平均温度',field:'averageTemperatureC',unit:'temperature'},{id:'Density',name:'仪表密度',field:'instrumentDensityKgM3',unit:'density'},{id:'CurrentVolume',name:'当前体积',field:'currentVolumeM3',unit:'volume'},{id:'NetVolume',name:'净体积',field:'netVolumeM3',unit:'volume'},{id:'Mass',name:'质量',field:'massT',unit:'mass'},{id:'Pressure1',name:'压力1',field:'pressure1KPa',unit:'pressure'},{id:'Pressure2',name:'压力2',field:'pressure2KPa',unit:'pressure'}];
const quantities=computed(()=>definitions.filter(d=>d.id!=='Interface'));
const states:Record<string,string>={All:'全部状态',Good:'正常',Invalid:'全部无效',Missing:'无数据',Offline:'通讯中断',Expired:'数据过期',Fault:'故障',Unconfigured:'未配置'};
const defaults:Item[]=['Level','InstantTemperature','AverageTemperature','Density','NetVolume','Mass'];
function restored():Item[]{try{const saved=JSON.parse(localStorage.getItem('level.history.columns.v1')||'null');if(Array.isArray(saved)){const valid=definitions.filter(d=>saved.includes(d.id)).map(d=>d.id);if(valid.length)return valid}}catch{}return [...defaults]}
const selected=ref<Item[]>(restored()),columns=computed(()=>definitions.filter(d=>selected.value.includes(d.id)));
watch(selected,v=>{try{localStorage.setItem('level.history.columns.v1',JSON.stringify(v))}catch{}},{deep:true});
let applied='';
function metric(r:Row,d:typeof definitions[number]):Metric{return (r[d.field] as Metric|undefined)||{value:null,quality:'Unconfigured',isValid:false,reason:'历史未提供'}}
function matchedMetric(r:Row){const id=new URLSearchParams(applied).get('quantity')||'Level';return metric(r,definitions.find(d=>d.id===id)!)}
function label(d:typeof definitions[number]){return d.name+' '+(d.unit==='pressure'?'kPa':unit(d.unit,props.config.display))}
function value(r:Row,d:typeof definitions[number]){const m=metric(r,d);return d.unit==='pressure'?(m.quality==='Good'&&m.value!==null?m.value:'—'):displayMetric(m,d.unit,props.config.display)}
function localInput(ms:number){const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
async function load(next=false){if(busy.value)return;if(!selected.value.length){error.value='请至少选择一个显示数据项。';return}busy.value=true;error.value='';try{const requested=next?applied:new URLSearchParams({start:new Date(start.value).toISOString(),end:new Date(end.value).toISOString(),tank:tank.value,limit:'500',quantity:quantity.value,quality:quality.value}).toString();const query=new URLSearchParams(requested);if(next&&page.value?.next){query.set('afterAt',String(page.value.next.atUtcMs));query.set('afterTank',String(page.value.next.tankKey))}const loaded=await api<HistoryPage>('/api/history?'+query);applied=requested;page.value=loaded}catch(e){error.value=String(e)}finally{busy.value=false}}
function print(){if(!page.value||!can('DataExport'))return;const q=new URLSearchParams(applied);previewPrint({title:'历史数据 · 当前页',readPermission:'HistoryRead',scope:['已查询范围：'+new Date(q.get('start')!).toLocaleString('zh-CN',{hour12:false})+' 至 '+new Date(q.get('end')!).toLocaleString('zh-CN',{hour12:false})+'（结束不含）','储罐：'+(props.config.tanks.find(t=>t.id===q.get('tank'))?.code||'全部储罐')+' · 状态 '+(states[q.get('quality')||'All']||'全部状态'),'仅打印当前页 '+page.value.rows.length+' 条；数据列按当前勾选，不自动查询其他页。'],sections:[{title:'历史记录',headers:['时间','储罐',...columns.value.map(label),'筛选项状态','配置记录','计量依据'],rows:page.value.rows.map(r=>[new Date(r.atUtcMs).toLocaleString('zh-CN',{hour12:false}),props.config.tanks.find(t=>t.id===r.tankId)?.code||r.tankId,...columns.value.map(d=>String(value(r,d))+'（'+qualityNames[metric(r,d).quality]+'）'),qualityNames[matchedMetric(r).quality],r.configurationRevision,r.calculationRevision])}]})}
function currentPage(){if(!page.value||!columns.value.length)return;window.LocalWorkbook.download('历史数据当前页',[{name:'历史数据',rows:[['时间','储罐',...columns.value.flatMap(d=>[label(d),d.name+' 状态']),'筛选数据项状态','系统配置记录号','计量依据记录号'],...page.value.rows.map(r=>[new Date(r.atUtcMs).toLocaleString('zh-CN',{hour12:false}),props.config.tanks.find(t=>t.id===r.tankId)?.code||r.tankId,...columns.value.flatMap(d=>[value(r,d),qualityNames[metric(r,d).quality]]),qualityNames[matchedMetric(r).quality],r.configurationRevision,r.calculationRevision])]}])}
async function exportAll(){if(busy.value||!page.value||!selected.value.length)return;busy.value=true;error.value='';try{const q=new URLSearchParams(applied);await api('/api/history/export','POST',{startUtcMs:Date.parse(q.get('start')!),endUtcMs:Date.parse(q.get('end')!),tankId:q.get('tank')==='all'?null:q.get('tank'),includeAtsPoints:ats.value,qualityQuantity:q.get('quantity'),quality:q.get('quality'),selectedQuantities:columns.value.map(d=>d.id)});message.value='已按已查询条件和当前勾选数据项申请Excel导出；在下方“历史导出任务”下载文件。';await jobs.value?.load()}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><div class="history-screen">
<p v-if="error" role="alert" class="notice error-message">{{error}}</p><p v-if="message" role="status" class="notice success-message">{{message}}</p>
<form class="panel query-panel history-query" @submit.prevent="load()"><div class="query-fields"><label class="config-field">储罐<select v-model="tank" aria-label="历史储罐"><option value="all">全部储罐</option><option v-for="t in config.tanks" :key="t.id" :value="t.id">{{t.code}}</option></select></label><label class="config-field">开始时间<input v-model="start" type="datetime-local" required aria-label="历史开始时间"></label><label class="config-field">结束时间（不含）<input v-model="end" type="datetime-local" required aria-label="历史结束时间"></label><label class="config-field">状态筛选依据<select v-model="quantity" aria-label="历史状态数据项"><option v-for="d in quantities" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="config-field">数据状态<select v-model="quality" aria-label="历史数据状态"><option v-for="(name,key) in states" :key="key" :value="key">{{name}}</option></select></label></div>
<fieldset class="history-data-items"><legend>显示数据项（可多选）</legend><div class="history-item-options"><label v-for="d in definitions" :key="d.id" class="checkbox"><input v-model="selected" type="checkbox" :value="d.id" :aria-label="'显示'+d.name">{{d.name}}</label><button type="button" class="text-button" @click="selected=definitions.map(d=>d.id)">全选</button><button type="button" class="text-button" @click="selected=[...defaults]">恢复默认</button></div></fieldset><div class="inline-actions"><button class="button primary" :disabled="busy||!selected.length">查询</button><span class="help">进入本页不自动查询。建议先选择储罐和时间范围；无有效数据的字段显示“—”。</span></div></form>
<section class="panel history-results"><div class="toolbar"><span>每页最多500条；导出沿用已查询条件，数据列按当前勾选</span><div><button class="button" :disabled="!can('DataExport')||busy||!page?.rows.length||!selected.length" @click="print">打印当前页预览</button><button class="button" :disabled="!can('DataExport')||busy||!page?.rows.length||!selected.length" @click="currentPage">导出当前页</button><button class="button" :disabled="!can('DataExport')||busy||!page||!selected.length" @click="exportAll">导出全部查询结果（Excel）</button><button class="button" :disabled="busy||!page?.next||!selected.length" @click="load(true)">下一页</button></div></div><label class="checkbox history-ats-option"><input v-model="ats" type="checkbox">全部导出时另含16点ATS温度及状态</label><div class="table-wrap"><table><thead><tr><th>时间</th><th>储罐</th><th v-for="d in columns" :key="d.id">{{label(d)}}</th><th>筛选数据项状态</th><th>记录依据</th></tr></thead><tbody><tr v-for="r in page?.rows" :key="r.tankId+':'+r.atUtcMs"><td>{{new Date(r.atUtcMs).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{config.tanks.find(t=>t.id===r.tankId)?.code||r.tankId}}</td><td v-for="d in columns" :key="d.id" :title="qualityNames[metric(r,d).quality]">{{value(r,d)}}</td><td>{{qualityNames[matchedMetric(r).quality]}}</td><td><button class="text-button" @click="basis=r">查看说明</button></td></tr><tr v-if="!page?.rows.length"><td :colspan="columns.length+4" class="empty">{{page?'暂无符合条件的历史记录。':'尚未查询，请选择条件后点击“查询”。'}}</td></tr></tbody></table></div></section>
<details class="history-export-tasks"><summary>历史导出任务</summary><DataJobs ref="jobs" kind="HistoryExport" title="历史导出任务"/></details>
<div v-if="basis" class="modal-backdrop"><section class="modal history-basis" role="dialog" aria-label="历史记录依据说明"><div class="modal-head"><h2>历史记录依据说明</h2><button class="button" @click="basis=null">关闭</button></div><div class="modal-body"><p>{{config.tanks.find(t=>t.id===basis!.tankId)?.code||basis.tankId}} · {{new Date(basis.atUtcMs).toLocaleString('zh-CN',{hour12:false})}}</p><h3>系统配置记录号：{{basis.configurationRevision}}</h3><p>表示保存这条历史数据时采用的系统设置记录，例如储罐、通讯、报警及计量设置。修改设置后会形成新的配置记录。</p><h3>计量依据记录号：{{basis.calculationRevision||'未形成计量依据记录'}}</h3><p>用于追溯当时采用的罐容表版本、静压修正表、人工水体积和压力换算等设置组合。它不是软件版本，也不是单张罐容表的版本号。</p><p class="notice">历史数据保留当时的结果；后来修改罐容表或参数，不会重新计算、覆盖旧记录。</p></div></section></div>
</div></template>